int main() {
    int choice = 0;
    cin >> choice;

    switch (choice) {
        case 1:
            cout << "我们要一条三文鱼" << endl;
            break;
        case 2:
            cout << "我们要一条秋刀鱼" << endl;
            break;
        case 3:
            cout << "我们要一条鳕鱼" << endl;
            break;
        default:
            cout << "这个编号我们不认识" << endl;
            break;
    }
    return 0;
}

